+.acc-trigger span:last-child { color: var(--green); transition: transform .18s ease; }
+.acc-item.open .acc-trigger span:last-child { transform: rotate(45deg); }
+.acc-content { display: none; padding: 0 1rem 1rem; color: var(--muted); }
+.acc-item.open .acc-content { display: block; }
+.acc-content ol { margin: .2rem 0 0 1.1rem; padding: 0; line-height: 1.75; }
+.tabs { display: flex; gap: .45rem; padding: .8rem .9rem 0; }
