+.footer strong { color: var(--text); }
+
+.docs-shell { display: grid; grid-template-columns: 280px minmax(0, 1fr); gap: 2rem; width: min(1380px, calc(100% - 2rem)); margin: 0 auto; padding-top: 1.4rem; }
